            float k0 = r0 * du + a0, k1 = r1 * du + a1, k2 = r2 * du + a2;
            float z = k2 > 1e-3f ? k2 : 1e-3f, iz = f_ / z, uk = k0 * iz + cx_, vk = k1 * iz + cy_;
            int ok = uk >= -0.5f && uk <= LC_W - 0.5f && vk >= -0.5f && vk <= LC_H - 0.5f && k2 > 1e-3f;
            float val = 0;
