                    double var = sw2 - sw1 * sw1 / NN;
                    double z = var > 1e-6 ? sd / (tn * sqrt(var)) : -1;
                    cc[(dy + S) * sw + dx + S] = z;
                    if (z > best) { best = z; bx = dx; by = dy; }
