        double ox = 2.0 * (cu + bx + sbx + m->offx), oy = 2.0 * (cv + by + sby + m->offy);
        double r2[2] = {(ox - cx) / fx - Pc[0] / Pc[2], (oy - cy) / fy - Pc[1] / Pc[2]};
        /* Jacobian wrt the current IMU rotation and position (as in feature_rows) */
